function employeeOverviewPanel(e){return `<section class="employee-detail-grid"><div class="employee-main-stack"><article class="card card-pad"><div class="card-head"><div><h2>基本资料</h2><p>敏感字段按权限脱敏展示</p></div>${status(e.archive==='完整'?'档案完整':'待补资料',e.archive==='完整'?'good':'warn')}</div><div class="employee-info-grid">${[['员工编号',e.id],['姓名',e.name],['在职状态',e.employment],['手机号码','已脱敏 · 授权可见'],['飞书账号','已绑定'],['身份同步','正常']].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div></article><article class="card card-pad"><div class="card-head"><div><h2>任职信息</h2><p>当前有效的组织与岗位关系</p></div></div><div class="employee-info-grid">${[['部门',e.department],['岗位',e.position],['直属负责人',e.manager],['入职日期',e.joinDate],['用工状态',e.employment],['数据权限','按岗位与角色授权']].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div></article></div><aside class="employee-side-stack"><article class="card card-pad"><div class="card-head"><div><h2>今日状态</h2><p>来自飞书考勤事实</p></div>${status(e.today,e.today==='正常'?'good':e.today==='外出'?'info':'warn')}</div><div class="employee-quick-metrics"><div><small>本月出勤</small><b>18 / 18天</b></div><div><small>异常待确认</small><b>0项</b></div></div></article><article class="card card-pad"><div class="card-head"><div><h2>待办提醒</h2><p>员工生命周期事项</p></div></div><div class="health-list"><div class="health-row"><span>劳动合同到期</span><b>${e.contractEnd}</b></div><div class="health-row"><span>档案缺失</span><b>${e.archive==='完整'?'0项':'1项'}</b></div><div class="health-row"><span>账号同步</span><b>正常</b></div></div></article></aside></section>`}
function employeeHistoryPanel(e){return `<article class="card card-pad employee-tab-card"><div class="card-head"><div><h2>任职经历</h2><p>入职、转正、转岗和离职记录均保留历史版本</p></div></div><div class="employee-timeline"><div class="employee-history-item current"><span></span><div><b>当前任职 · ${e.position}</b><small>${e.department} · ${e.employment} · 当前有效</small></div></div><div class="employee-history-item"><span></span><div><b>完成入职并建立员工档案</b><small>${e.joinDate} · 组织身份与飞书账号同步</small></div></div></div><div class="empty-note">暂无转岗、离职或返聘记录</div></article>`}
function employeeContractPanel(e){return `<section class="employee-detail-grid"><article class="card card-pad"><div class="card-head"><div><h2>劳动合同</h2><p>合同版本、期限与签署事实可追溯</p></div>${status('生效中','good')}</div><div class="employee-info-grid">${[['合同类型','固定期限劳动合同'],['合同主体','中泰旭鼎'],['开始日期',e.joinDate],['结束日期',e.contractEnd],['签署状态','已签署'],['原件状态','已归档']].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div></article><aside class="card card-pad"><div class="card-head"><div><h2>档案附件</h2><p>仅记录归档状态，不公开证件明文</p></div></div><div class="archive-list">${[['身份与入职资料','已归档'],['劳动合同','已归档'],['保密与知识产权协议','已归档'],['岗位或转岗确认材料',e.archive==='完整'?'已归档':'待补充']].map(x=>`<div><span>${x[0]}</span>${status(x[1],x[1]==='已归档'?'good':'warn')}</div>`).join('')}</div></aside></section>`}
function employeeAttendancePanel(e){const rows=[['07-23',e.today,'09:01','—','飞书同步'],['07-22','正常','08:58','18:12','飞书同步'],['07-21','正常','09:03','18:20','飞书同步'],['07-20','休息日','—','—','日历规则']];return `<section class="employee-attendance-summary"><article class="card mini-stat"><small>本月应出勤</small><strong>18天</strong><p>按飞书考勤组日历</p></article><article class="card mini-stat"><small>实际出勤</small><strong>18天</strong><p>不含请假与外出</p></article><article class="card mini-stat"><small>请假 / 外出</small><strong>${e.today==='请假'?'1 / 0':e.today==='外出'?'0 / 1':'0 / 0'}</strong><p>审批事实同步</p></article><article class="card mini-stat"><small>异常待确认</small><strong>0</strong><p>迟到、缺卡或旷工</p></article></section><article class="card data-card"><div class="card-head card-pad" style="margin:0"><div><h2>近期考勤事实</h2><p>系统使用飞书事实，不重复维护打卡规则</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>日期</th><th>状态</th><th>首次打卡</th><th>末次打卡</th><th>数据来源</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x[0]}</td><td>${status(x[1],x[1]==='正常'?'good':x[1]==='休息日'?'':x[1]==='外出'?'info':'warn')}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td></tr>`).join('')}</tbody></table></div></article>`}
function employeeDetailPage(i){const e=employees[i]||employees[0],tabs=[['overview','档案总览'],['history','任职经历'],['contract','合同与档案'],['attendance','飞书考勤']],panel=state.peopleTab==='history'?employeeHistoryPanel(e):state.peopleTab==='contract'?employeeContractPanel(e):state.peopleTab==='attendance'?employeeAttendancePanel(e):employeeOverviewPanel(e);return `<div class="employee-detail-head"><button class="button" data-people-back>← 返回员工列表</button><div class="employee-identity"><span class="employee-avatar">${e.name[0]}</span><div><div class="employee-name-line"><h1>${e.name}</h1>${status(e.employment,e.employment==='正式'?'good':'warn')}</div><p>${e.id} · ${e.department} · ${e.position}</p></div></div><div class="employee-head-meta"><small>直属负责人</small><b>${e.manager}</b><small>入职日期</small><b>${e.joinDate}</b></div></div><div class="tabs employee-tabs">${tabs.map(x=>`<button class="tab ${state.peopleTab===x[0]?'active':''}" data-people-tab="${x[0]}">${x[1]}</button>`).join('')}</div>${panel}`}
function pagePeople(){if(state.employeeIndex!==null)return employeeDetailPage(state.employeeIndex);return head('员工管理','管理入职、档案、转岗、离职、劳动合同和飞书考勤事实。','<button class="button">组织架构</button><button class="button primary" data-action="new-employee">＋ 新增员工</button>')+`<section class="kpi-grid"><article class="card kpi"><div class="kpi-top"><span class="kpi-icon">人</span><span class="delta">本月 +3</span></div><span class="kpi-label">在职员工</span><strong class="kpi-value">48</strong><span class="kpi-note">正式 42 · 试用 6</span></article><article class="card kpi"><div class="kpi-top"><span class="kpi-icon">入</span><span class="delta">流程中</span></div><span class="kpi-label">待入职</span><strong class="kpi-value">2</strong><span class="kpi-note">资料待补充 1</span></article><article class="card kpi"><div class="kpi-top"><span class="kpi-icon">合</span><span class="delta down">需关注</span></div><span class="kpi-label">合同即将到期</span><strong class="kpi-value">4</strong><span class="kpi-note">30天内到期</span></article><article class="card kpi"><div class="kpi-top"><span class="kpi-icon">勤</span><span class="delta">飞书同步</span></div><span class="kpi-label">今日出勤</span><strong class="kpi-value">44</strong><span class="kpi-note">请假 2 · 外出 2</span></article></section><div class="toolbar"><div class="filters"><input class="control search" placeholder="搜索姓名、部门或岗位"><select class="select"><option>全部部门</option><option>市场销售中心</option><option>新媒体中心</option><option>讲师部</option></select><select class="select"><option>全部状态</option><option>正式</option><option>试用</option><option>离职流程中</option></select></div></div><article class="card data-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>员工</th><th>部门</th><th>岗位</th><th>直属负责人</th><th>入职日期</th><th>劳动合同</th><th>今日状态</th></tr></thead><tbody>${employees.map((e,i)=>`<tr data-employee-record="${i}"><td><div class="entity"><span class="entity-icon">${e.name[0]}</span><span><b>${e.name}</b><small>${e.id} · 档案${e.archive}</small></span></div></td><td>${e.department}</td><td>${e.position}</td><td>${e.manager}</td><td>${e.joinDate}</td><td>${e.contractEnd}</td><td>${status(e.today,e.today==='正常'?'good':e.today==='外出'?'info':'warn')}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>点击员工进入完整档案</span><span>敏感个人信息按权限脱敏展示</span></div></article>`}
const orgDepartments=[
  {name:'经营管理层',count:1,head:'王晨',scope:'经营决策、目标校准与全公司经营监控',roles:'经营管理负责人'},
  {name:'市场销售中心',count:12,head:'赵宁',scope:'线索、客户、商机、合同与回款协同',roles:'销售经理、客户经理'},
  {name:'新媒体中心',count:11,head:'周敏',scope:'内容生产、账号运营、直播与品宣交付',roles:'品宣、主播、运营'},
  {name:'技术交付中心',count:9,head:'陈浩',scope:'AI定制项目实施、技术支持与项目交付',roles:'项目经理、技术支持'},
  {name:'讲师部',count:7,head:'陈浩',scope:'培训交付、课程研发、讲师工时与排期',roles:'高级讲师、讲师'},
  {name:'综合管理部',count:5,head:'待维护',scope:'员工生命周期、绩效规则、校准与申诉',roles:'人事、行政、绩效'},
  {name:'财务部',count:3,head:'待维护',scope:'合同财务、工资核算、复核与发放',roles:'会计、出纳'}
];
function organizationPage(){return `<div class="page-head"><div><button class="button" data-people-org-back>← 返回员工管理</button><h1 style="margin-top:14px">组织架构</h1><p>单一公司组织口径 · 部门、负责人和在职人数来自员工档案。</p></div><div class="page-actions"><span class="demo-chip">演示数据</span><button class="button primary" data-action="new-employee">＋ 新增员工</button></div></div><section class="org-summary"><article class="card mini-stat"><small>公司主体</small><strong>1</strong><p>中泰旭鼎</p></article><article class="card mini-stat"><small>一级组织</small><strong>7</strong><p>管理层与职能部门</p></article><article class="card mini-stat"><small>在职员工</small><strong>48</strong><p>正式42 · 试用6</p></article><article class="card mini-stat"><small>负责人待维护</small><strong>2</strong><p>综合管理部、财务部</p></article></section><article class="card org-chart"><div class="org-company-node"><span class="org-company-mark">中</span><div><small>公司主体</small><h2>中泰旭鼎</h2><p>48名在职员工 · 7个一级组织</p></div>${status('飞书组织同步正常','good')}</div><div class="org-trunk" aria-hidden="true"></div><div class="org-department-grid">${orgDepartments.map((d,i)=>`<button class="org-department-card" data-org-department="${i}"><span class="org-dept-icon">${d.name[0]}</span><div><small>一级组织 · ${d.count}人</small><b>${d.name}</b><p>负责人：${d.head}</p></div><span class="org-open">查看 ›</span></button>`).join('')}</div></article><article class="card data-card org-responsibility"><div class="card-head card-pad" style="margin:0"><div><h2>部门职责与岗位范围</h2><p>用于员工归属、权限、绩效和跨部门协作路由</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>组织</th><th>负责人</th><th>主要职责</th><th>主要岗位</th><th>在职人数</th></tr></thead><tbody>${orgDepartments.map((d,i)=>`<tr data-org-department="${i}"><td><b>${d.name}</b></td><td>${d.head}</td><td>${d.scope}</td><td>${d.roles}</td><td>${d.count}</td></tr>`).join('')}</tbody></table></div></article>`}
function openOrgDepartment(i){const d=orgDepartments[i],members=employees.filter(x=>x.department===d.name);openDrawer('组织详情',d.name,`<div class="detail-section"><div class="detail-summary">${status(`${d.count}人在职`,'info')}<small>一级组织 · 负责人 ${d.head}</small></div></div><div class="detail-section"><h3>部门职责</h3><p style="color:var(--ink-2);line-height:1.7">${d.scope}</p><div class="detail-grid"><div class="detail-cell"><small>主要岗位</small><b>${d.roles}</b></div><div class="detail-cell"><small>负责人</small><b>${d.head}</b></div></div></div><div class="detail-section"><h3>员工档案示例</h3><div class="notification-list">${members.length?members.map(x=>`<button class="notification-item" data-org-employee="${employees.indexOf(x)}"><span class="notification-mark">${x.name[0]}</span><span><b>${x.name}</b><small>${x.position} · ${x.employment}</small></span><span class="notification-time">查看</span></button>`).join(''):'<div class="empty-note">当前演示数据未列出该部门具体员工</div>'}</div>${members.length<d.count?`<p class="notification-note">另有 ${d.count-members.length} 名员工未在演示列表展开</p>`:''}</div>`,`<button class="button" data-close-drawer>关闭</button>`);$$('[data-org-employee]',$('#drawerBody')).forEach(x=>x.onclick=()=>{closeDrawer();state.peopleMode='list';state.employeeIndex=+x.dataset.orgEmployee;state.peopleTab='overview';render('people')})}
const pagePeopleListBase=pagePeople;
function pagePeopleComplete(){if(state.employeeIndex!==null)return employeeDetailPage(state.employeeIndex);if(state.peopleMode==='org')return organizationPage();return pagePeopleListBase().replace('<button class="button">组织架构</button>','<button class="button" data-people-org>组织架构</button>').replace('<strong class="kpi-value">2</strong><span class="kpi-note">资料待补充 1</span>',`<strong class="kpi-value">${2+Math.max(0,employees.length-7)}</strong><span class="kpi-note">资料待补充 ${1+Math.max(0,employees.length-7)}</span>`)}
pagePeople=pagePeopleComplete;
function pageKnowledge(){return head('AI知识库','从已授权的飞书工作群和云文档中沉淀可追溯的企业知识。','<button class="button">来源授权</button><button class="button primary" data-action="new-source">＋ 添加知识源</button>')+`<section class="knowledge-layout"><aside class="card knowledge-side reveal"><div class="card-head"><div><h2>知识空间</h2><p>按权限显示可访问内容</p></div></div><div class="source-item active"><span class="source-icon">全</span><span><b>全部知识</b><small>1,286 条已发布</small></span></div><div class="source-item"><span class="source-icon">销</span><span><b>销售方法与产品</b><small>312 条</small></span></div><div class="source-item"><span class="source-icon">项</span><span><b>项目交付规范</b><small>468 条</small></span></div><div class="source-item"><span class="source-icon">媒</span><span><b>新媒体运营</b><small>286 条</small></span></div><div class="source-item"><span class="source-icon">制</span><span><b>制度与流程</b><small>220 条</small></span></div><div class="card-head" style="margin-top:22px"><div><h3>采集状态</h3></div>${status('正常','good')}</div><div class="health-list"><div class="health-row"><span>授权工作群</span><b>12</b></div><div class="health-row"><span>云文档目录</span><b>8</b></div><div class="health-row"><span>待审核条目</span><b>18</b></div><div class="health-row"><span>同步失败</span><b style="color:var(--warn)">2</b></div></div></aside><div class="knowledge-main"><article class="card knowledge-search reveal"><h2>向企业知识库提问</h2><p>答案仅基于你有权访问的内容，并附带来源、版本和更新时间。</p><div class="ask-box"><input id="knowledgeQuestion" value="AI定制项目延期时，需要走什么变更流程？" aria-label="知识库问题"><button class="button primary" id="askKnowledge">生成答案</button></div></article><article class="card answer-card reveal" id="answerCard"><div class="answer-head"><span class="ai-mark">知</span><div><b>基于 3 个已授权来源整理</b><small style="display:block;color:var(--ink-3);margin-top:3px">检索时间 09:44 · 内容版本已校验</small></div></div><div class="answer-copy"><p><strong>项目预计延期时，需要先提交项目变更申请，不能直接修改原计划。</strong></p><p>项目负责人应说明延期原因、受影响的里程碑、交付物、人员和成本，并提交新的计划基线。涉及客户承诺变化时，需要同步商务责任人和客户确认。审批完成后，系统保存原基线和新版本，并重新计算项目健康度。</p><p>如果延期已经触发跨部门协作或验收风险，还需要关联对应工单和风险事项。例外放行必须填写原因并获得授权。</p></div><div class="citation"><span class="source-icon">1</span><span><b>《项目变更与基线管理规范》</b><small>云文档 · V3.2 · 更新于 2026-07-18</small></span></div><div class="citation"><span class="source-icon">2</span><span><b>星河制造项目周会纪要</b><small>授权工作群 · 2026-07-21 16:08</small></span></div><div class="citation"><span class="source-icon">3</span><span><b>《客户交付异常处理流程》</b><small>云文档 · V2.1 · 更新于 2026-07-09</small></span></div></article></div></section>`}
function pageTicketsV2(){const cols=['待接收','处理中','待确认','已关闭'];return head('协作工单','项目任务跨部门协作统一形成工单，由时限规则、处理结果和发起人验收推动闭环。','<button class="button" data-action="sla-rules">工单时限规则</button><button class="button primary" data-action="new-ticket">＋ 发起工单</button>')+`<section class="ticket-kpis"><div><small>接近时限</small><b>2</b></div><div><small>已逾期</small><b style="color:var(--down)">1</b></div><div><small>待发起人确认</small><b>${state.ticketStatus.filter(x=>x==='待确认').length}</b></div><div><small>本月满意度</small><b>4.7 / 5</b></div></section><div class="toolbar"><div class="filters"><select class="select"><option>全部项目</option><option>星河制造数据平台</option><option>北辰账号矩阵</option></select><select class="select"><option>全部部门</option><option>技术支持</option><option>讲师部</option><option>财务部</option></select></div><span class="demo-chip">分类时限 · 50%与80%提醒 · 超时逐级升级</span></div><section class="ticket-board">${cols.map((c,ci)=>`<div class="ticket-column reveal"><div class="column-head"><b><i style="background:${['var(--ink-3)','var(--accent)','var(--warn)','var(--up)'][ci]}"></i>${c}</b><span>${state.ticketStatus.filter(x=>x===c).length}张</span></div>${tickets.map((t,i)=>({t,i})).filter(x=>state.ticketStatus[x.i]===c).sort((a,b)=>b.i-a.i).map(({t,i})=>`<article class="ticket-card" data-ticket="${i}"><div class="ticket-id"><span>${t[0]}</span>${status(t[4],t[4]==='高'?'bad':t[4]==='中'?'warn':'')}</div><h3>${t[1]}</h3><div class="ticket-tags"><span class="status">${t[2]}</span><span class="status info">${t[3]}</span></div><div class="ticket-link">${t[6]||['RW-072301','SCH-072298','PJ-260721','RW-072286','RW-072268','HT-260724'][i]||'未关联'}</div><div class="ticket-footer"><span class="mini-avatar">${t[7]||['许','周','财','林','教','综'][i]||'我'}</span><span style="color:${t[5].includes('逾期')?'var(--down)':''}">${c==='已关闭'?'已关闭 · 可重开':t[5]}</span></div></article>`).join('')}</div>`).join('')}</section>`}
const scheduleItems=[['SCH-072301','AI销售方法内训','内部培训','周启明','讲师','07-23','10:00–11:30','RW-072298','待讲师确认','待同步'],['SCH-072298','企业AI落地沙龙','外部沙龙','林溪','讲师','07-23','14:30–16:30','PJ-260721','已确认','已同步'],['SCH-072286','品牌直播专场','项目直播','安然','主播','07-24','19:00–21:00','RW-072255','已确认','已同步'],['SCH-072272','客户沙龙彩排','外部沙龙','周启明','讲师','07-24','14:00–16:00','TK-072298','冲突待协调','未同步'],['SCH-072255','产品功能直播','项目直播','许嘉','主播','07-25','20:00–22:00','PJ-260705','已完成','已同步']];
function pageScheduleV2(){const action=state.scheduleTab==='sync'?'<button class="button" data-action="retry-sync">重试失败任务</button>':'<button class="button primary" data-action="new-meeting">＋ 新建排期</button>';return head('排期与会议','项目任务、讲师、主播和会议使用统一人员占用，并与实际工时分开记录。',action)+`<div class="tabs"><button class="tab ${state.scheduleTab==='week'?'active':''}" data-schedule-tab="week">统一周视图</button><button class="tab ${state.scheduleTab==='instructor'?'active':''}" data-schedule-tab="instructor">讲师排期</button><button class="tab ${state.scheduleTab==='anchor'?'active':''}" data-schedule-tab="anchor">主播排期</button><button class="tab ${state.scheduleTab==='sync'?'active':''}" data-schedule-tab="sync">飞书同步</button></div>${state.scheduleTab==='sync'?scheduleSyncPanel():state.scheduleTab==='instructor'?scheduleResourcePanel('讲师'):state.scheduleTab==='anchor'?scheduleResourcePanel('主播'):scheduleWeekPanel()}`}
function scheduleWeekPanel(){return `<section class="schedule-summary"><article class="card mini-stat"><small>本周排期</small><strong>28</strong><p>已确认22项</p></article><article class="card mini-stat"><small>人员冲突</small><strong style="color:var(--down)">2</strong><p>均未占用生效</p></article><article class="card mini-stat"><small>待本人确认</small><strong>3</strong><p>讲师2 · 主播1</p></article><article class="card mini-stat"><small>实际工时待填</small><strong>4</strong><p>活动完成后填报</p></article></section>${scheduleTable(scheduleItems)}`}
function scheduleResourcePanel(role){const rows=scheduleItems.filter(x=>x[4]===role);return `<section class="resource-load reveal">${(role==='讲师'?[['周启明','82%','2项待确认'],['林溪','68%','本周4场']]:[['安然','74%','本周3场'],['许嘉','56%','1项待填工时']]).map(x=>`<article class="card resource-card"><span class="mini-avatar">${x[0][0]}</span><div><b>${x[0]}</b><small>${x[2]}</small></div><div class="load-meter"><span style="width:${x[1]}"></span></div><strong>${x[1]}</strong></article>`).join('')}</section>${scheduleTable(rows)}`}
function scheduleRelation(ref){if(ref.startsWith('RW-')){const i=projectTasks.findIndex(x=>x[0]===ref),task=projectTasks[i];return task?`<button class="relation-object" data-related-task="${i}" title="打开项目任务：${task[1]}"><span>项目任务</span><b>${ref}</b><small>${task[1]}</small></button>`:`<span class="relation-object static"><span>项目任务</span><b>${ref}</b></span>`}if(ref.startsWith('PJ-'))return `<span class="relation-object static"><span>项目</span><b>${ref}</b></span>`;if(ref.startsWith('TK-'))return `<span class="relation-object static"><span>协作工单</span><b>${ref}</b></span>`;return `<span class="relation-object static"><span>其他关联</span><b>${ref}</b></span>`}
function scheduleRelationText(ref){if(ref.startsWith('RW-')){const task=projectTasks.find(x=>x[0]===ref);return task?`项目任务 · ${ref} · ${task[1]}`:`项目任务 · ${ref}`}if(ref.startsWith('PJ-'))return `项目 · ${ref}`;if(ref.startsWith('TK-'))return `协作工单 · ${ref}`;return ref}
function scheduleTable(rows){return `<article class="card data-card reveal"><div class="table-wrap"><table class="data-table"><thead><tr><th>排期事项</th><th>类型</th><th>人员</th><th>角色</th><th>日期时间</th><th>关联业务</th><th>确认状态</th><th>飞书日历</th></tr></thead><tbody>${rows.map(r=>{const i=scheduleItems.indexOf(r),confirmed=state.scheduleConfirmed.includes(i)?'已确认':r[8],completed=state.scheduleCompleted.includes(i)?'已完成':confirmed;return `<tr data-schedule="${i}"><td><div class="entity"><span class="entity-icon">${r[0].slice(-2)}</span><span><b>${r[1]}</b><small>${r[0]}</small></span></div></td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>${r[5]} · ${r[6]}</td><td>${scheduleRelation(r[7])}</td><td>${status(completed,completed==='已完成'||completed==='已确认'?'good':completed.includes('冲突')?'bad':'warn')}</td><td>${status(r[9],r[9]==='已同步'?'good':r[9]==='未同步'?'':'warn')}</td></tr>`}).join('')}</tbody></table></div><div class="table-footer"><span>关联业务可追溯到项目任务、项目或协作工单</span><span>实际工时不由排期时长自动覆盖</span></div></article>`}
function scheduleSyncPanel(){return `<section class="kpi-grid"><article class="card kpi"><div class="kpi-top"><span class="kpi-icon">同</span><span class="delta">近24小时</span></div><span class="kpi-label">同步成功</span><strong class="kpi-value">36</strong><span class="kpi-note">平均延迟1m 24s</span></article><article class="card kpi"><div class="kpi-top"><span class="kpi-icon">待</span><span class="delta">队列</span></div><span class="kpi-label">等待同步</span><strong class="kpi-value">3</strong><span class="kpi-note">内部排期已生效</span></article><article class="card kpi"><div class="kpi-top"><span class="kpi-icon">失</span><span class="delta down">需处理</span></div><span class="kpi-label">同步失败</span><strong class="kpi-value">1</strong><span class="kpi-note">已自动重试2次</span></article><article class="card kpi"><div class="kpi-top"><span class="kpi-icon">更</span><span class="delta">版本记录</span></div><span class="kpi-label">日程变更</span><strong class="kpi-value">5</strong><span class="kpi-note">均保留内部结果</span></article></section><article class="card data-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>同步任务</th><th>业务排期</th><th>动作</th><th>内部状态</th><th>外部状态</th><th>最后尝试</th><th>失败原因</th></tr></thead><tbody><tr><td><b>SYNC-072311</b></td><td>SCH-072272 · 客户沙龙彩排</td><td>创建事件</td><td>${status('冲突待协调','warn')}</td><td>${status('未提交')}</td><td>无</td><td>人员冲突，未进入同步</td></tr><tr><td><b>SYNC-072306</b></td><td>SCH-072286 · 品牌直播专场</td><td>更新事件</td><td>${status('已确认','good')}</td><td>${status('同步失败','bad')}</td><td>10:18</td><td>飞书接口暂时不可用</td></tr><tr><td><b>SYNC-072301</b></td><td>SCH-072298 · 企业AI落地沙龙</td><td>创建事件</td><td>${status('已确认','good')}</td><td>${status('已同步','good')}</td><td>09:42</td><td>无</td></tr></tbody></table></div><div class="table-footer"><span>外部同步失败不回滚内部排期</span><span>恢复后重试并记录每次结果</span></div></article>`}
function pageScheduleV3(){const action=state.scheduleTab==='sync'?'<button class="button" data-action="retry-sync">重试失败任务</button>':'<button class="button primary" data-action="new-meeting">＋ 新建排期</button>';return head('排期与会议','项目任务、讲师、主播和会议使用统一人员占用，并与实际工时分开记录。',action)+`<div class="tabs"><button class="tab ${state.scheduleTab==='week'?'active':''}" data-schedule-tab="week">统一周视图</button><button class="tab ${state.scheduleTab==='month'?'active':''}" data-schedule-tab="month">统一月视图</button><button class="tab ${state.scheduleTab==='instructor'?'active':''}" data-schedule-tab="instructor">讲师排期</button><button class="tab ${state.scheduleTab==='anchor'?'active':''}" data-schedule-tab="anchor">主播排期</button><button class="tab ${state.scheduleTab==='sync'?'active':''}" data-schedule-tab="sync">飞书同步</button></div>${state.scheduleTab==='sync'?scheduleSyncPanel():state.scheduleTab==='instructor'?scheduleResourcePanel('讲师'):state.scheduleTab==='anchor'?scheduleResourcePanel('主播'):state.scheduleTab==='month'?scheduleMonthCalendarPanel():scheduleWeekCalendarPanel()}`}
function closeMonthPopovers(){if(typeof $$!=='function')return;$$('.month-day.popover-open').forEach(x=>{x.classList.remove('popover-open');x.querySelector('[data-month-overflow]')?.setAttribute('aria-expanded','false')})}
function scheduleMonthCalendarPanel(){const events={21:[['AI产品内训','10:00 · 周启明',0,'pending','待确认']],23:[['销售方法内训','10:00 · 周启明',0,'pending','待确认'],['企业AI落地沙龙','14:30 · 林溪',1,'confirmed','已确认'],['客户项目周会','14:30 · 周启明',null,'conflict','有冲突']],24:[['直播脚本评审','11:45 · 安然',2,'confirmed','已确认']],25:[['产品功能直播','10:45 · 许嘉',4,'completed','已完成']]};const item=(x,cls)=>`<button class="${cls} ${x[3]}" ${x[2]===null?`data-month-summary="${x[0]}"`:`data-schedule="${x[2]}"`}><span class="event-state">${x[4]}</span><b>${x[0]}</b><small>${x[1]}</small></button>`,days=[29,30,...Array.from({length:31},(_,i)=>i+1),1,2];return `<article class="card month-calendar-card reveal"><div class="month-calendar-title"><div><h2>2026年7月</h2><p>统一查看会议、讲师和主播占用</p></div><div class="month-legend"><span><i class="confirmed"></i>已确认</span><span><i class="pending"></i>待确认</span><span><i class="conflict"></i>有冲突</span><span><i class="completed"></i>已完成</span></div></div><div class="month-weekdays">${['周一','周二','周三','周四','周五','周六','周日'].map(x=>`<span>${x}</span>`).join('')}</div><div class="month-grid">${days.map((d,i)=>{const current=i>=2&&i<33,today=current&&d===23,items=current?(events[d]||[]):[],overflow=items.length>2;return `<div class="month-day ${current?'':'muted'} ${today?'today':''} ${overflow?'has-overflow':''}" ${overflow?'data-month-day-overflow':''}><div class="month-day-number"><b>${d}</b>${today?'<span>今天</span>':''}</div><div class="month-events">${items.slice(0,2).map(x=>item(x,'month-event')).join('')}${overflow?`<button class="month-more" data-month-overflow aria-expanded="false"><b>+${items.length-2}项</b><span>共${items.length}项</span></button>`:''}</div>${overflow?`<div class="month-day-popover" role="dialog" aria-label="7月${d}日全部排期"><div class="month-popover-head"><div><small>7月${d}日</small><b>当天全部排期</b></div><span>共${items.length}项</span></div><div class="month-popover-list">${items.map(x=>item(x,'month-popover-event')).join('')}</div><p>点击排期可查看详情</p></div>`:''}</div>`}).join('')}</div></article>`}
function scheduleWeekCalendarPanel(){return `<section class="calendar-shell"><article class="card calendar-card reveal"><div class="calendar-head"><div></div>${['周一 21','周二 22','周三 23','周四 24','周五 25'].map((x,i)=>`<div>${x.split(' ')[0]}<strong>${x.split(' ')[1]}</strong>${i===2?'<span class="status info">今天</span>':''}</div>`).join('')}</div><div class="calendar-grid"><div class="time-col">${['09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00'].map(x=>`<span>${x}</span>`).join('')}</div><div class="day-col"><div class="event pending" style="top:10%;height:16%" data-schedule="0"><span class="event-state">待确认</span><b>AI产品内训</b><small>10:00 · 周启明</small></div><div class="event conflict" style="top:52%;height:24%" data-schedule="3"><span class="event-state">有冲突</span><b>客户沙龙彩排</b><small>14:00 · 周启明</small></div></div><div class="day-col"><div class="event confirmed" style="top:20%;height:18%"><span class="event-state">已确认</span><b>项目启动会</b><small>11:00 · 陈浩</small></div></div><div class="day-col"><div class="event pending" style="top:9%;height:14%" data-schedule="0"><span class="event-state">待确认</span><b>销售方法内训</b><small>10:00 · 周启明</small></div><div class="event confirmed" style="top:52%;height:20%" data-schedule="1"><span class="event-state">已确认</span><b>企业AI落地沙龙</b><small>14:30 · 林溪</small></div><div class="event conflict" style="top:58%;height:16%;left:34%"><span class="event-state">有冲突</span><b>客户项目周会</b><small>14:30 · 周启明</small></div></div><div class="day-col"><div class="event confirmed" style="top:28%;height:16%" data-schedule="2"><span class="event-state">已确认</span><b>直播脚本评审</b><small>11:45 · 安然</small></div></div><div class="day-col"><div class="event completed" style="top:18%;height:24%" data-schedule="4"><span class="event-state">已完成</span><b>产品功能直播</b><small>10:45 · 许嘉</small></div></div></div></article><aside class="calendar-side"><article class="card card-pad reveal"><div class="card-head"><div><h2>冲突提醒</h2><p>时间和人员重复占用</p></div>${status('2项','bad')}</div><div class="alert-list"><div class="alert-row danger"><span class="alert-symbol">!</span><span><b>周启明 14:30 时间冲突</b><small>外部沙龙 / 客户项目周会</small></span></div><div class="alert-row"><span class="alert-symbol">↻</span><span><b>1条日历同步失败</b><small>已自动重试2次</small></span></div></div></article><article class="card card-pad reveal"><div class="card-head"><div><h2>人员负载</h2><p>本周已确认排期</p></div></div><div class="person-list">${[['周启明','讲师','82%'],['林溪','讲师','68%'],['安然','主播','74%'],['许嘉','主播','56%']].map(x=>`<div class="person-row"><span class="mini-avatar">${x[0][0]}</span><span><b>${x[0]}</b><small>${x[1]}</small></span><span class="util">${x[2]}</span></div>`).join('')}</div></article><article class="card card-pad reveal"><div class="card-head"><div><h2>飞书日历</h2><p>内部记录为主，外部同步可补偿</p></div>${status('正常','good')}</div><div class="health-list"><div class="health-row"><span>今日成功同步</span><b>18</b></div><div class="health-row"><span>等待重试</span><b>1</b></div><div class="health-row"><span>平均延迟</span><b>1m 24s</b></div></div></article></aside></section>`}
const pages={overview:pageOverview,sales:pageSales,projects:pageProjectsV3,tickets:pageTicketsV2,schedule:pageScheduleV3,performance:pagePerformance,people:pagePeople,knowledge:pageKnowledge};
function render(view=state.view){state.view=view;history.replaceState(null,'',`${location.pathname}?view=${view}`);main.innerHTML=pages[view]();$('#breadcrumb').innerHTML=`<span>经营中心</span><b>/</b><strong>${names[view]}</strong>`;$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));window.scrollTo({top:0,behavior:'instant'});bindPage();if(view==='overview'){drawRevenue();drawFunnel();animateCounts()}}
function drawRevenue(){const income=[72,86,94,108,116,128],cash=[58,64,79,84,96,91],labels=['2月','3月','4月','5月','6月','7月'];const W=720,H=220,padX=40,padY=22,max=140;const x=i=>padX+i*(W-padX*2)/(labels.length-1),y=v=>H-padY-v/max*(H-padY*2);const path=a=>'M'+a.map((v,i)=>`${x(i)},${y(v)}`).join(' L');const area=path(income)+` L${x(5)},${H-padY} L${x(0)},${H-padY} Z`;$('#revenueChart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="2月至7月收入与回款趋势图"><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".22"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>${[0,35,70,105,140].map(v=>`<line class="grid-line" x1="${padX}" x2="${W-padX}" y1="${y(v)}" y2="${y(v)}"/><text class="axis-label" x="4" y="${y(v)+4}">${v}</text>`).join('')}<path class="chart-area" d="${area}"/><path class="chart-line" d="${path(income)}"/> <path d="${path(cash)}" fill="none" stroke="var(--accent-2)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>${income.map((v,i)=>`<circle class="chart-point" cx="${x(i)}" cy="${y(v)}" r="4"><title>${labels[i]} 确认收入 ${v}万元</title></circle>`).join('')}${labels.map((l,i)=>`<text class="axis-label" text-anchor="middle" x="${x(i)}" y="${H-2}">${l}</text>`).join('')}</svg>`}
function drawFunnel(){const data=[['录入线索',286],['有效线索',142],['形成商机',64],['方案报价',31],['赢单',9]],max=286;$('#funnel').innerHTML=data.map(x=>`<div class="funnel-row"><span>${x[0]}</span><div class="funnel-track"><div class="funnel-fill" style="width:${x[1]/max*100}%"></div></div><b>${x[1]}</b></div>`).join('')}
function animateCounts(){if(matchMedia('(prefers-reduced-motion:reduce)').matches){$$('[data-count]').forEach(el=>el.textContent=(el.dataset.count==='1286000'?'¥':'')+fmt(el.dataset.count));return}$$('[data-count]').forEach(el=>{const target=+el.dataset.count,start=performance.now();const money=target>100000;function tick(now){const p=Math.min(1,(now-start)/850),v=Math.round(target*(1-Math.pow(1-p,3)));el.textContent=(money?'¥':'')+fmt(v);if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)})}
