function openContract(i){const r=contracts[i],events=state.contractEvents[i],balance=Number(r[3].replaceAll(',',''))-Number(r[4].replaceAll(',',''));openDrawer('合同详情',r[0],`<div class="detail-section"><div class="detail-summary"><span>${status(r[6],r[6]==='已收齐'?'good':'info')}</span><small>${r[1]} · ${r[2]}</small></div></div><div class="detail-section"><h3>金额与履约</h3><div class="detail-grid"><div class="detail-cell"><small>合同金额</small><b>¥${r[3]}</b></div><div class="detail-cell"><small>已确认收款</small><b>¥${r[4]}</b></div><div class="detail-cell"><small>未收余额</small><b>¥${fmt(balance)}</b></div><div class="detail-cell"><small>下一收款日</small><b>${r[5]}</b></div></div></div><div class="detail-section"><h3>收款计划</h3><div class="payment-plan"><div><span>首付款</span><b>¥${r[4]}</b>${status('已确认','good')}</div><div><span>下一期</span><b>¥${fmt(balance)}</b>${status(balance===0?'已完成':'待收款',balance===0?'good':'warn')}</div></div></div><div class="detail-section"><h3>操作轨迹</h3><div class="timeline">${salesTimeline(events,[['合同台账已生效','07-18 11:20 · 审批流程'],['应收计划已生成','07-18 11:21 · 系统']])}</div></div>`,`<button class="button" id="editPaymentPlan">查看 / 变更收款计划</button>${balance>0?'<button class="button primary" id="claimContractReceipt">提交到款认领</button>':''}`);$('#editPaymentPlan')?.addEventListener('click',()=>{closeDrawer();paymentPlanModal(i)});$('#claimContractReceipt')?.addEventListener('click',()=>{closeDrawer();receiptClaimModal(i)})}
