function openAcceptance(i){if(i===0&&state.projectAccepted)return closeoutModal();if(i===0)return projectAcceptanceModal();openDrawer('内部验收详情',i===1?'嘉禾教育AI培训':'北辰零售账号矩阵',`<div class="detail-section"><h3>内部验收状态</h3><div class="health-list"><div class="health-row"><span>交付物</span><b>${i===1?'8 / 8':'7月清单完成'}</b></div><div class="health-row"><span>内部确认</span><b>${i===1?'等待内部确认':'阶段内部确认已记录'}</b></div><div class="health-row"><span>遗留问题</span><b>${i===1?'0项':'2项，不阻断本期确认'}</b></div></div></div>`,`<button class="button" data-close-drawer>关闭</button>`)}
