function openProjectTask(i){const r=projectTasks[i],actual=state.worklogs[i]||r[7];openDrawer('项目任务',r[1],`<div class="detail-section"><div class="detail-summary">${status(r[8],r[8]==='已完成'?'good':r[8]==='已逾期'?'bad':r[8]==='待排期'?'warn':'info')}<small>${r[0]} · ${r[2]}</small></div></div><div class="detail-section"><h3>任务责任与时间</h3><div class="detail-grid"><div class="detail-cell"><small>责任人</small><b>${r[3]}</b></div><div class="detail-cell"><small>所属部门</small><b>${r[4]}</b></div><div class="detail-cell"><small>截止日期</small><b>${r[5]}</b></div><div class="detail-cell"><small>计划 / 实际工时</small><b>${r[6]} / ${actual}h</b></div></div></div><div class="detail-section"><h3>协同关联</h3><div class="health-list"><div class="health-row"><span>上级里程碑</span><b>系统联调</b></div><div class="health-row"><span>关联工单或排期</span><b>${r[9]}</b></div><div class="health-row"><span>完成证据</span><b>${r[8]==='已完成'?'已提交':'待提交'}</b></div></div></div><div class="detail-section"><h3>最近记录</h3><div class="timeline"><div class="timeline-item"><b>任务进度更新为${r[8]}</b><small>今天 09:18 · ${r[3]}</small></div><div class="timeline-item"><b>计划工时确认</b><small>项目基线生效时 · 项目负责人</small></div></div></div>`,`<button class="button" id="createTaskTicket">发起协作工单</button>${r[8]==='待排期'?'<button class="button" id="arrangeTaskSchedule">安排人员排期</button>':''}<button class="button primary" id="logTaskHours">填报实际工时</button>`);$('#createTaskTicket')?.addEventListener('click',()=>{closeDrawer();ticketModal(i)});$('#arrangeTaskSchedule')?.addEventListener('click',()=>{closeDrawer();scheduleFromTaskModal(i)});$('#logTaskHours')?.addEventListener('click',()=>{closeDrawer();worklogModal(i)})}
function openEmployeeMonitor(i){const rows=[['许哲','12','9','1','40 / 36h','100%','82%','2'],['陈浩','10','7','2','40 / 44h','90%','88%','3'],['周言','8','7','0','32 / 30h','100%','68%','1'],['苏木','9','6','1','36 / 28h','78%','64%','2']],r=rows[i];openDrawer('员工执行下钻',r[0],`<div class="detail-section"><h3>本周执行摘要</h3><div class="detail-grid"><div class="detail-cell"><small>任务完成</small><b>${r[2]} / ${r[1]}</b></div><div class="detail-cell"><small>逾期任务</small><b>${r[3]}</b></div><div class="detail-cell"><small>计划 / 实际工时</small><b>${r[4]}</b></div><div class="detail-cell"><small>排期负载</small><b>${r[6]}</b></div></div></div><div class="detail-section"><h3>需要关注</h3><div class="health-list"><div class="health-row"><span>工时记录完整率</span><b>${r[5]}</b></div><div class="health-row"><span>待处理工单</span><b>${r[7]}张</b></div><div class="health-row"><span>数据范围</span><b>本部门授权事项</b></div></div></div>`,`<button class="button" data-close-drawer>关闭</button><button class="button primary" id="notifyEmployee">发送执行提醒</button>`);$('#notifyEmployee')?.addEventListener('click',()=>toast('提醒已发送',`已通知${r[0]}查看逾期任务、工时或工单事项。`))}
function openTicketV2(i){const t=tickets[i],s=state.ticketStatus[i],link=t[6]||['RW-072301','SCH-072298','PJ-260721','RW-072286','RW-072268','HT-260724'][i]||'未关联',transfers=state.ticketTransfers[i]||[],transfer=transfers[0];let actions=s==='待接收'?'<button class="button primary" id="acceptTicketV2">接单处理</button>':s==='处理中'?'<button class="button" id="transferTicket">转派</button><button class="button primary" id="submitTicketResult">提交处理结果</button>':s==='待确认'?'<button class="button danger" id="returnTicket">退回处理</button><button class="button primary" id="closeTicket">验收并关闭</button>':'<button class="button" id="reopenTicket">3个工作日内重开</button>';openDrawer('工单处理与确认',t[0],`<div class="detail-section"><div class="detail-summary">${status(s,s==='已关闭'?'good':s==='待确认'?'warn':'info')}<small>${t[5]} · ${t[4]}优先级</small></div></div><div class="detail-section"><h3>${t[1]}</h3><p style="color:var(--ink-2);line-height:1.7">请承接部门按期提供可验收结果，处理过程和状态变化完整留痕。</p><div class="detail-grid"><div class="detail-cell"><small>发起部门</small><b>${t[2]}</b></div><div class="detail-cell"><small>承接部门</small><b>${t[3]}</b></div><div class="detail-cell"><small>当前处理人</small><b>${transfer?transfer.person:'承接部门处理中'}</b></div><div class="detail-cell"><small>关联业务</small><b>${link}</b></div><div class="detail-cell"><small>验收角色</small><b>发起人</b></div></div></div><div class="detail-section"><h3>SLA与升级</h3><div class="health-list"><div class="health-row"><span>当前时限</span><b>${t[5]}</b></div><div class="health-row"><span>提醒节点</span><b>50%与80%</b></div><div class="health-row"><span>超时升级</span><b>承接部门负责人 → 项目或发起部门负责人</b></div></div></div><div class="detail-section"><h3>流转记录</h3><div class="timeline"><div class="timeline-item"><b>当前状态：${s}</b><small>最近更新 · 系统</small></div>${transfers.map(x=>`<div class="timeline-item"><b>已转派给 ${x.department} · ${x.person}</b><small>${x.time} · 原因：${x.reason} · 处理时限继续计算</small></div>`).join('')}<div class="timeline-item"><b>工单已创建并通知承接部门</b><small>刚刚 · 发起人</small></div></div></div>`,actions);$('#acceptTicketV2')?.addEventListener('click',()=>{state.ticketStatus[i]='处理中';closeDrawer();render('tickets');toast('工单已接收','SLA继续计时，处理责任已记录。')});$('#submitTicketResult')?.addEventListener('click',()=>{closeDrawer();ticketResultModal(i)});$('#returnTicket')?.addEventListener('click',()=>{state.ticketStatus[i]='处理中';closeDrawer();render('tickets');toast('已退回处理','发起人填写的差异说明已通知承接部门。')});$('#closeTicket')?.addEventListener('click',()=>{closeDrawer();ticketCloseModal(i)});$('#reopenTicket')?.addEventListener('click',()=>{state.ticketStatus[i]='处理中';closeDrawer();render('tickets');toast('工单已重新打开','原处理记录保留，SLA按重开规则继续计算。')});$('#transferTicket')?.addEventListener('click',()=>{closeDrawer();ticketTransferModal(i)})}
function openSchedule(i){const r=scheduleItems[i],confirmed=state.scheduleConfirmed.includes(i)?'已确认':r[8],completed=state.scheduleCompleted.includes(i);let actions;if(completed)actions='<button class="button" data-close-drawer>关闭</button>';else if(confirmed.includes('冲突'))actions='<button class="button primary" id="coordinateSchedule">协调冲突</button>';else if(confirmed==='待讲师确认')actions='<button class="button danger" id="declineSchedule">请求协调</button><button class="button primary" id="confirmSchedule">确认本人档期</button>';else actions='<button class="button" id="changeSchedule">变更安排</button><button class="button primary" id="completeSchedule">完成活动并填工时</button>';openDrawer('人员排期',r[1],`<div class="detail-section"><div class="detail-summary">${status(completed?'已完成':confirmed,completed||confirmed==='已确认'?'good':confirmed.includes('冲突')?'bad':'warn')}<small>${r[0]} · ${r[2]}</small></div></div><div class="detail-section"><h3>时间与人员</h3><div class="detail-grid"><div class="detail-cell"><small>人员与角色</small><b>${r[3]} · ${r[4]}</b></div><div class="detail-cell"><small>日期时间</small><b>${r[5]} · ${r[6]}</b></div><div class="detail-cell"><small>关联业务</small><b>${scheduleRelationText(r[7])}</b></div><div class="detail-cell"><small>飞书日历</small><b>${r[9]}</b></div></div></div><div class="detail-section"><h3>冲突与确认</h3><div class="health-list"><div class="health-row"><span>人员冲突检查</span><b>${confirmed.includes('冲突')?'发现重叠占用':'无阻断冲突'}</b></div><div class="health-row"><span>本人档期确认</span><b>${confirmed}</b></div><div class="health-row"><span>实际工时</span><b>${completed?'已填报':'活动完成后填报'}</b></div></div></div>`,actions);$('#confirmSchedule')?.addEventListener('click',()=>{state.scheduleConfirmed.push(i);closeDrawer();render('schedule');toast('档期已确认','内部排期已生效并进入飞书日历同步队列。')});$('#declineSchedule')?.addEventListener('click',()=>toast('已请求协调','原排期保持待确认，不占用已确认档期。'));$('#coordinateSchedule')?.addEventListener('click',()=>toast('冲突处理已发起','请调整时间或选择替代人员后重新确认。'));$('#completeSchedule')?.addEventListener('click',()=>{closeDrawer();completeScheduleModal(i)});$('#changeSchedule')?.addEventListener('click',()=>toast('进入排期变更','时间或人员变化后需要重新检查冲突和本人确认。'))}
function showModal(eyebrow,title,body,actions){$('#modalEyebrow').textContent=eyebrow;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalActions').innerHTML=actions;$('#modal').showModal()}
function employeeOnboardingModal(){const managers={'经营管理层':'—','市场销售中心':'赵宁','新媒体中心':'周敏','技术交付中心':'陈浩','讲师部':'陈浩','综合管理部':'待维护','财务部':'待维护'};showModal('员工建档','新增待入职员工',section(1,'基础信息',`<div class="form-grid"><div class="field"><label>姓名 <em>*</em></label><input id="employeeName" placeholder="填写员工姓名"></div><div class="field"><label>手机号码 <em>*</em></label><input id="employeePhone" inputmode="tel" placeholder="用于飞书身份匹配"></div><div class="field"><label>员工编号</label><input value="提交后自动生成" disabled></div><div class="field"><label>入职日期 <em>*</em></label><input id="employeeJoinDate" type="date" value="2026-08-01"></div></div>`)+section(2,'任职关系',`<div class="form-grid"><div class="field"><label>所属部门 <em>*</em></label><select id="employeeDepartment">${orgDepartments.map(x=>`<option>${x.name}</option>`).join('')}</select></div><div class="field"><label>岗位 <em>*</em></label><input id="employeePosition" placeholder="填写岗位名称"></div><div class="field"><label>直属负责人</label><input id="employeeManager" value="王晨" disabled></div><div class="field"><label>用工状态 <em>*</em></label><select id="employeeEmployment"><option>试用</option><option>正式</option></select></div></div>`)+section(3,'合同与档案',`<div class="form-grid"><div class="field"><label>合同类型 <em>*</em></label><select><option>固定期限劳动合同</option><option>无固定期限劳动合同</option></select></div><div class="field"><label>合同开始日期 <em>*</em></label><input id="employeeContractStart" type="date" value="2026-08-01"></div><div class="field"><label>合同结束日期 <em>*</em></label><input id="employeeContractEnd" type="date" value="2029-07-31"></div><div class="field"><label>档案资料状态</label><select id="employeeArchive"><option>待补1项</option><option>完整</option></select></div></div>`)+section(4,'飞书与生效检查',`<div class="health-list"><div class="health-row"><span>飞书组织身份</span><b>入职日创建或绑定</b></div><div class="health-row"><span>考勤事实</span><b>同步所属部门考勤组</b></div><div class="health-row"><span>系统权限</span><b>按部门与岗位生成待确认授权</b></div><div class="health-row"><span>操作记录</span><b>完整保留提交人与时间</b></div></div>`),`<button class="button" value="cancel">保存草稿</button><button class="button primary" id="confirmEmployeeOnboarding">建立待入职档案</button>`);const department=$('#employeeDepartment'),manager=$('#employeeManager'),joinDate=$('#employeeJoinDate'),contractStart=$('#employeeContractStart');department.onchange=()=>manager.value=managers[department.value]||'待维护';joinDate.onchange=()=>contractStart.value=joinDate.value;$('#confirmEmployeeOnboarding').onclick=e=>{e.preventDefault();const name=$('#employeeName').value.trim(),phone=$('#employeePhone').value.trim(),position=$('#employeePosition').value.trim(),end=$('#employeeContractEnd').value;if(!name||!phone||!position||!joinDate.value||!end)return toast('员工信息未完整','姓名、手机、岗位、入职日期和合同期限均为必填项。');const id=`YG-${String(employees.length+47).padStart(4,'0')}`;employees.push({id,name,department:department.value,position,manager:manager.value,joinDate:joinDate.value,contractEnd:end,today:'待入职',employment:'待入职',archive:$('#employeeArchive').value});$('#modal').close();state.peopleMode='list';state.employeeIndex=null;render('people');toast('待入职档案已建立',`${name} · ${id} 已加入员工列表，飞书身份将在入职日创建或绑定。`)}}
function handleAction(a){if(a==='new-meeting')return meetingModal();if(a==='new-lead')return leadModal();if(a==='import-leads')return importLeadsModal();if(a==='new-opportunity')return opportunityModal();if(a==='claim-receipt')return receiptClaimModal();if(a==='new-initiation')return initiationModal();if(a==='project-baseline')return projectBaselineModal();if(a==='project-risk')return projectRiskModal();if(a==='project-change')return projectChangeModal();if(a==='project-acceptance')return projectAcceptanceModal();if(a==='new-project-task')return projectTaskModal();if(a==='new-employee')return employeeOnboardingModal();if(a==='sla-rules')return slaRulesModal();if(a==='new-ticket')return ticketModal();if(a==='retry-sync')return toast('已加入重试队列','内部排期不变，新的飞书同步结果将继续留痕。');if(a==='export')return toast('正在生成经营简报','完成后将提供受控下载链接，并写入导出审计。');if(a==='calibrate')return toast('校准流程已准备','当前仍有2项申诉处理中，暂不能锁定结果。');toast('原型交互已触发','该操作将在详细设计阶段接入正式流程。')}
function slaRulesModal(){showModal('工单规则','响应、处理与超时规则',section(1,'这项规则是什么',`<div class="notice-block"><b>SLA 即工单服务时限</b><small>系统根据工单分类计算响应和完成时限，并持续显示剩余时间。具体数值由有权限的管理员配置。</small></div>`)+section(2,'当前执行方式',`<div class="health-list"><div class="health-row"><span>项目交付工单</span><b>2个工作小时内响应 · 完成时间按项目计划</b></div><div class="health-row"><span>普通跨部门协作</span><b>具体时长由管理员配置</b></div><div class="health-row"><span>紧急客户或生产问题</span><b>具体时长由管理员配置</b></div></div>`)+section(3,'提醒与升级',`<div class="health-list"><div class="health-row"><span>已使用时限达到50%</span><b>提醒当前处理人</b></div><div class="health-row"><span>已使用时限达到80%</span><b>再次提醒处理人和负责人</b></div><div class="health-row"><span>超过处理时限</span><b>逐级通知承接部门及业务负责人</b></div><div class="health-row"><span>等待发起人验收期间</span><b>暂停处理计时</b></div></div>`),`<button class="button primary" value="cancel">我知道了</button>`)}
