function projectTaskModal(){showModal('项目任务','新建执行任务',section(1,'任务归属',`<div class="form-grid"><div class="field"><label>所属项目 <em>*</em></label><select><option>星河制造数据平台</option><option>北辰账号矩阵</option></select></div><div class="field"><label>上级里程碑 <em>*</em></label><select><option>系统联调</option><option>用户验收测试</option></select></div><div class="field full"><label>任务名称 <em>*</em></label><input id="newTaskTitle" placeholder="填写可交付、可验收的任务结果"></div><div class="field full"><label>完成标准 <em>*</em></label><textarea id="newTaskCriteria" placeholder="说明需要提交的成果和验收口径"></textarea></div></div>`)+section(2,'责任与计划',`<div class="form-grid"><div class="field"><label>责任人 <em>*</em></label><select><option>许哲 · 技术支持</option><option>周启明 · 讲师部</option><option>林溪 · 新媒体部</option></select></div><div class="field"><label>截止日期 <em>*</em></label><input type="date" value="2026-07-28"></div><div class="field"><label>计划工时 <em>*</em></label><input id="newTaskHours" inputmode="numeric" placeholder="小时"></div><div class="field"><label>是否需要人员排期</label><select><option>否</option><option>是，创建后安排</option></select></div></div>`)+section(3,'创建后关联',`<div class="health-list"><div class="health-row"><span>✓ 项目与里程碑</span><b>建立追溯关系</b></div><div class="health-row"><span>ⓘ 跨部门协作</span><b>需要时从任务发起工单</b></div><div class="health-row"><span>ⓘ 实际工时</span><b>由责任人另行填报</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmProjectTask">创建任务</button>`);$('#confirmProjectTask').onclick=e=>{e.preventDefault();if(!$('#newTaskTitle').value.trim()||!$('#newTaskCriteria').value.trim()||!$('#newTaskHours').value)return toast('任务信息未完整','任务名称、完成标准和计划工时均为必填项。');$('#modal').close();toast('项目任务已创建','已通知责任人，后续工时、工单和排期均关联此任务。')}}
function worklogModal(i){const r=projectTasks[i];showModal('实际工时',`填报 ${r[1]}`,section(1,'工时归属',`<div class="commit-summary"><div><small>项目任务</small><b>${r[0]}</b></div><div><small>责任人</small><b>${r[3]}</b></div><div><small>计划工时</small><b>${r[6]}h</b></div></div>`)+section(2,'本次实际投入',`<div class="form-grid"><div class="field"><label>工作日期 <em>*</em></label><input id="worklogDate" type="date" value="2026-07-23"></div><div class="field"><label>实际工时 <em>*</em></label><input id="actualHours" inputmode="decimal" placeholder="例如 2.5"></div><div class="field full"><label>完成内容与产出 <em>*</em></label><textarea id="worklogOutput" placeholder="记录实际完成内容、交付物或问题"></textarea></div></div>`)+section(3,'偏差提示',`<div class="health-list"><div class="health-row"><span>ⓘ 排期时长</span><b>不自动作为实际工时</b></div><div class="health-row"><span>ⓘ 累计实际工时</span><b>${state.worklogs[i]||r[7]}h</b></div><div class="health-row"><span>✓ 绩效证据</span><b>审核后可引用</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmWorklog">提交工时</button>`);$('#confirmWorklog').onclick=e=>{e.preventDefault();const h=Number($('#actualHours').value);if(!h||h<=0||!$('#worklogOutput').value.trim())return toast('工时信息未完整','实际工时必须大于0，并填写完成内容。');state.worklogs[i]=Number(state.worklogs[i]||r[7])+h;$('#modal').close();render('projects');toast('实际工时已提交',`本次${h}小时已关联${r[0]}，计划工时保持不变。`)}}
function scheduleFromTaskModal(i){const r=projectTasks[i];showModal('任务排期','安排讲师或主播',section(1,'关联任务',`<div class="commit-summary"><div><small>任务</small><b>${r[0]}</b></div><div><small>项目</small><b>${r[2]}</b></div><div><small>计划工时</small><b>${r[6]}h</b></div></div>`)+section(2,'人员和时间',`<div class="form-grid"><div class="field"><label>人员角色 <em>*</em></label><select><option>讲师</option><option>主播</option></select></div><div class="field"><label>指定人员 <em>*</em></label><select><option>周启明 · 讲师</option><option>林溪 · 讲师</option><option>安然 · 主播</option></select></div><div class="field"><label>开始时间 <em>*</em></label><input type="datetime-local" value="2026-07-28T14:00"></div><div class="field"><label>结束时间 <em>*</em></label><input type="datetime-local" value="2026-07-28T16:00"></div></div>`)+section(3,'确认路径',`<div class="health-list"><div class="health-row"><span>✓ 项目任务关联</span><b>${r[0]}</b></div><div class="health-row"><span>ⓘ 冲突与负荷</span><b>提交时检查</b></div><div class="health-row"><span>ⓘ 人员本人</span><b>确认后占用生效</b></div><div class="health-row"><span>ⓘ 飞书日历</span><b>确认后同步</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmTaskSchedule">提交排期需求</button>`);$('#confirmTaskSchedule').onclick=e=>{e.preventDefault();$('#modal').close();state.scheduleTab='instructor';render('schedule');toast('排期需求已提交','无阻断冲突，当前等待讲师本人确认。')}}
function ticketTransferModal(i){const t=tickets[i];showModal('工单转派',`转派 ${t[0]}`,section(1,'当前责任',`<div class="detail-grid"><div class="detail-cell"><small>当前承接部门</small><b>${t[3]}</b></div><div class="detail-cell"><small>工单状态</small><b>处理中</b></div></div>`)+section(2,'新的承接责任',`<div class="form-grid"><div class="field full"><label>新承接部门与处理人 <em>*</em></label><select id="ticketTransferTarget"><option value="">请选择</option><option value="技术支持|许哲">技术支持 · 许哲</option><option value="技术支持|陈浩">技术支持 · 陈浩</option><option value="讲师部|周启明">讲师部 · 周启明</option><option value="讲师部|林溪">讲师部 · 林溪</option><option value="财务部|林静">财务部 · 林静</option><option value="新媒体部|安然">新媒体部 · 安然</option></select><small>既可以转给同部门其他人员，也可以变更承接部门。</small></div><div class="field full"><label>转派原因 <em>*</em></label><textarea id="ticketTransferReason" placeholder="说明为何转派、当前已完成内容和需要继续处理的事项"></textarea></div></div>`)+section(3,'确认后影响',`<div class="health-list"><div class="health-row"><span>工单状态</span><b>保持处理中</b></div><div class="health-row"><span>处理时限</span><b>继续计算，不重新开始</b></div><div class="health-row"><span>责任通知</span><b>通知原处理方和新处理方</b></div><div class="health-row"><span>历史记录</span><b>原责任及转派原因完整保留</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmTicketTransfer">确认转派</button>`);$('#confirmTicketTransfer').onclick=e=>{e.preventDefault();const target=$('#ticketTransferTarget').value,reason=$('#ticketTransferReason').value.trim();if(!target||!reason)return toast('转派信息未完整','新承接责任和转派原因均为必填项。');const [department,person]=target.split('|');state.ticketTransfers[i]=[{department,person,reason,time:'刚刚'},...(state.ticketTransfers[i]||[])];t[3]=department;$('#modal').close();render('tickets');openTicketV2(i);toast('工单已转派',`${t[0]} 已转给 ${department} · ${person}，处理时限继续计算。`)}}
function ticketResultModal(i){const t=tickets[i];showModal('工单处理结果',`提交 ${t[0]} 结果`,section(1,'处理结果',`<div class="form-grid"><div class="field full"><label>结果说明 <em>*</em></label><textarea id="ticketResult" placeholder="说明已完成内容、差异和使用方式"></textarea></div><div class="field full"><label>成果附件或链接</label><input placeholder="飞书文档、文件或项目交付物链接"></div></div>`)+section(2,'提交后状态',`<div class="health-list"><div class="health-row"><span>✓ 处理责任和耗时</span><b>保留</b></div><div class="health-row"><span>ⓘ 工单状态</span><b>转为待发起人确认</b></div><div class="health-row"><span>ⓘ SLA</span><b>等待验收期间暂停处理计时</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmTicketResult">提交结果</button>`);$('#confirmTicketResult').onclick=e=>{e.preventDefault();if(!$('#ticketResult').value.trim())return toast('请填写结果说明','发起人需要依据结果说明完成验收。');state.ticketStatus[i]='待确认';$('#modal').close();render('tickets');toast('处理结果已提交','已通知发起人验收确认。')}}
function ticketCloseModal(i){const t=tickets[i];showModal('工单验收','确认结果并关闭',section(1,'验收结论',`<div class="radio-cards"><div class="radio-card selected" data-ticket-score="5"><b>5分 · 完全满足</b><small>结果符合期望，可直接关闭。</small></div><div class="radio-card" data-ticket-score="4"><b>4分 · 基本满足</b><small>有轻微差异，但不影响使用。</small></div></div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>验收备注</label><textarea placeholder="选填，记录差异或后续建议"></textarea></div></div>`)+section(2,'关闭后规则',`<div class="health-list"><div class="health-row"><span>✓ 处理结果</span><b>归档并关联原任务</b></div><div class="health-row"><span>ⓘ 满意度</span><b>用于部门协作统计</b></div><div class="health-row"><span>ⓘ 重开窗口</span><b>关闭后3个工作日</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmTicketClose">验收并关闭</button>`);$$('[data-ticket-score]').forEach(x=>x.onclick=()=>{$$('[data-ticket-score]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected')});$('#confirmTicketClose').onclick=e=>{e.preventDefault();state.ticketStatus[i]='已关闭';$('#modal').close();render('tickets');toast('工单已关闭',`${t[0]}验收结论已保存，3个工作日内可重开。`)}}
function completeScheduleModal(i){const r=scheduleItems[i];showModal('活动完成','确认结果与实际工时',section(1,'活动结果',`<div class="form-grid"><div class="field full"><label>完成结果 <em>*</em></label><textarea id="scheduleResult" placeholder="记录培训、直播或会议的实际结果"></textarea></div><div class="field"><label>实际开始时间 <em>*</em></label><input type="datetime-local" value="2026-07-23T14:35"></div><div class="field"><label>实际结束时间 <em>*</em></label><input type="datetime-local" value="2026-07-23T16:20"></div></div>`)+section(2,'实际工时',`<div class="form-grid"><div class="field"><label>本人实际工时 <em>*</em></label><input id="scheduleHours" inputmode="decimal" placeholder="小时"></div><div class="field"><label>关联任务</label><input value="${r[7]}" disabled></div></div><div class="notice-block"><b>排期时长不会自动覆盖实际工时</b><small>请按真实投入填报。提交后形成独立工时记录，并关联原排期与项目任务。</small></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmScheduleComplete">完成并提交工时</button>`);$('#confirmScheduleComplete').onclick=e=>{e.preventDefault();const h=Number($('#scheduleHours').value);if(!$('#scheduleResult').value.trim()||!h||h<=0)return toast('完成信息未完整','活动结果和大于0的实际工时均为必填项。');state.scheduleCompleted.push(i);$('#modal').close();render('schedule');toast('活动已完成',`${h}小时实际工时已关联${r[7]}，飞书日历保留原事件。`)}}
function recordOpportunityEvent(i,title){state.opportunityEvents[i]=[[title,'刚刚 · 王晨'],...(state.opportunityEvents[i]||[])]}
function opportunityModal(){showModal('新建商机','创建客户商机',section(1,'客户与负责人',`<div class="form-grid"><div class="field full"><label>客户主体 <em>*</em></label><select id="opportunityCustomer"><option value="">请选择已有客户</option><option>星河制造</option><option>嘉禾教育</option><option>云际科技</option></select><small>商机必须关联已完成查重的客户主体。</small></div><div class="field"><label>主负责人 <em>*</em></label><select><option>王晨 · 市场销售中心</option></select></div><div class="field"><label>业务类型 <em>*</em></label><select><option>AI产品销售</option><option>AI定制开发</option><option>自媒体代运营</option></select></div></div>`)+section(2,'商机信息',`<div class="form-grid"><div class="field full"><label>商机名称 <em>*</em></label><input id="newOpportunityName" placeholder="客户主体 + 需求项目"></div><div class="field"><label>初始阶段 <em>*</em></label><select><option>需求确认</option><option>方案报价</option><option>商务谈判</option></select></div><div class="field"><label>预计金额</label><input inputmode="numeric" placeholder="¥ 0"></div><div class="field full"><label>需求与成交依据 <em>*</em></label><textarea id="newOpportunityNeed" placeholder="记录需求范围、决策人、预算或关键时间点"></textarea></div></div>`)+section(3,'提交检查',`<div class="health-list"><div class="health-row"><span>ⓘ 客户主体</span><b>必须关联已有客户</b></div><div class="health-row"><span>ⓘ 当前主负责人</span><b>王晨</b></div><div class="health-row"><span>✓ 创建后操作轨迹</span><b>自动留痕</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmOpportunity">创建商机</button>`);$('#confirmOpportunity').onclick=e=>{e.preventDefault();if(!$('#opportunityCustomer').value||!$('#newOpportunityName').value.trim()||!$('#newOpportunityNeed').value.trim())return toast('请补全商机信息','客户主体、商机名称和需求依据均为必填项。');$('#modal').close();toast('商机已创建','已关联客户主体并设置唯一主负责人。')}}
function opportunityFollowupModal(i){const r=opportunities[i];showModal('销售动作',`记录 ${r[2]}`,section(1,'本次动作',`<div class="form-grid"><div class="field"><label>动作类型 <em>*</em></label><select id="salesAction"><option>需求访谈</option><option>方案沟通</option><option>报价说明</option><option>商务谈判</option></select></div><div class="field"><label>完成时间</label><input value="刚刚" disabled></div><div class="field full"><label>结果与证据 <em>*</em></label><textarea id="salesActionResult" placeholder="记录客户反馈、关键结论和可追溯材料"></textarea></div></div>`)+section(2,'下一步',`<div class="form-grid"><div class="field"><label>下一动作日期 <em>*</em></label><input type="date" id="nextSalesDate" value="2026-07-25"></div><div class="field"><label>下一动作</label><select><option>提交正式方案</option><option>发送报价</option><option>预约决策人会议</option><option>持续跟进</option></select></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmSalesAction">保存销售动作</button>`);$('#confirmSalesAction').onclick=e=>{e.preventDefault();if(!$('#salesActionResult').value.trim())return toast('请填写动作结果','销售动作必须有结果或证据。');recordOpportunityEvent(i,`${$('#salesAction').value}已完成`);$('#modal').close();toast('销售动作已保存','下一动作日期已更新并写入商机轨迹。')}}
function advanceOpportunityModal(i){const r=opportunities[i];showModal('阶段变更','更新销售阶段',section(1,'阶段选择',`<div class="form-grid"><div class="field"><label>当前阶段</label><input value="${r[4]}" disabled></div><div class="field"><label>目标阶段 <em>*</em></label><select id="targetStage"><option value="">请选择</option><option>需求确认</option><option>方案报价</option><option>商务谈判</option><option>赢单</option><option>输单</option></select></div><div class="field full"><label>变更依据 <em>*</em></label><textarea id="stageEvidence" placeholder="填写客户确认、报价记录或输单原因"></textarea></div></div>`)+section(2,'变更影响',`<div class="health-list"><div class="health-row"><span>✓ 原阶段记录</span><b>保留</b></div><div class="health-row"><span>ⓘ 选择赢单</span><b>下一步可发起合同</b></div><div class="health-row"><span>ⓘ 选择输单</span><b>商机关闭，客户档案保留</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmStage">确认变更</button>`);$('#confirmStage').onclick=e=>{e.preventDefault();if(!$('#targetStage').value||!$('#stageEvidence').value.trim())return toast('请补全阶段依据','目标阶段和变更依据均为必填项。');recordOpportunityEvent(i,`销售阶段更新为 ${$('#targetStage').value}`);$('#modal').close();toast('销售阶段已更新','原阶段、变更依据和操作者均已留痕。')}}
function contractDraftModal(i){const r=opportunities[i];showModal('合同申请','从商机发起合同',section(1,'合同主体',`<div class="form-grid"><div class="field"><label>客户主体</label><input value="${r[1]}" disabled></div><div class="field"><label>来源商机</label><input value="${r[0]}" disabled></div><div class="field full"><label>合同名称 <em>*</em></label><input id="contractName" value="${r[1]} · ${r[2]}服务合同"></div><div class="field"><label>合同金额 <em>*</em></label><input id="contractAmount" inputmode="numeric" value="${r[5].replaceAll(',','')}"></div><div class="field"><label>业务类型</label><input value="${r[3]}" disabled></div></div>`)+section(2,'履约与收款',`<div class="form-grid"><div class="field"><label>履约开始日期 <em>*</em></label><input type="date" value="2026-08-01"></div><div class="field"><label>履约结束日期 <em>*</em></label><input type="date" value="2026-10-31"></div><div class="field"><label>首付款比例 <em>*</em></label><select id="depositRatio"><option>50%</option><option>30%</option><option>100%</option></select></div><div class="field"><label>首付款计划日期 <em>*</em></label><input type="date" value="2026-07-31"></div><div class="field full"><label>合同文件 <em>*</em></label><div class="upload-box" id="contractUpload"><b>选择合同文件</b><small>PDF 或 Word · 单文件不超过20MB · 不接入电子签</small></div></div></div>`)+section(3,'提交检查',`<div class="health-list"><div class="health-row"><span>✓ 客户与商机</span><b>${r[1]} · ${r[0]}</b></div><div class="health-row"><span>ⓘ 审批与盖章</span><b>按公司权限流程执行</b></div><div class="health-row"><span>ⓘ 生效后</span><b>生成合同台账和应收计划</b></div></div>`),`<button class="button" value="cancel">保存草稿</button><button class="button primary" id="confirmContract">提交合同申请</button>`);let uploaded=false;$('#contractUpload').onclick=()=>{uploaded=true;$('#contractUpload').classList.add('uploaded');$('#contractUpload').innerHTML='<b>星河制造服务合同V3.pdf</b><small>已选择 · 2.8MB · 可重新选择</small>'};$('#confirmContract').onclick=e=>{e.preventDefault();if(!$('#contractName').value.trim()||!$('#contractAmount').value.trim()||!uploaded)return toast('合同申请未完整','请填写合同名称、金额并选择合同文件。');recordOpportunityEvent(i,'已提交合同申请');$('#modal').close();toast('合同申请已提交','审批通过后生成合同台账与应收计划，不发起电子签。')}}
function paymentPlanModal(i){const r=contracts[i],total=Number(r[3].replaceAll(',',''));showModal('收款计划','查看或申请变更',section(1,'合同金额',`<div class="commit-summary"><div><small>合同编号</small><b>${r[0]}</b></div><div><small>合同金额</small><b>¥${r[3]}</b></div><div><small>已确认收款</small><b>¥${r[4]}</b></div></div>`)+section(2,'计划节点',`<div class="form-grid"><div class="field"><label>下一期金额 <em>*</em></label><input id="planAmount" inputmode="numeric" value="${total-Number(r[4].replaceAll(',',''))}"></div><div class="field"><label>计划收款日期 <em>*</em></label><input id="planDate" type="date" value="2026-07-30"></div><div class="field full"><label>变更原因 <em>*</em></label><textarea id="planReason" placeholder="仅在需要修改原合同应收计划时填写"></textarea></div></div>`)+section(3,'版本影响',`<div class="health-list"><div class="health-row"><span>✓ 原收款计划</span><b>保留原版本</b></div><div class="health-row"><span>ⓘ 新计划</span><b>审批后生效</b></div><div class="health-row"><span>ⓘ 合同总额</span><b>本操作不修改</b></div></div>`),`<button class="button" value="cancel">关闭</button><button class="button primary" id="confirmPlanChange">提交变更申请</button>`);$('#confirmPlanChange').onclick=e=>{e.preventDefault();if(!$('#planAmount').value||!$('#planDate').value||!$('#planReason').value.trim())return toast('请填写变更信息','计划金额、日期和变更原因均为必填项。');state.contractEvents[i]=[['收款计划变更申请已提交','刚刚 · 王晨'],...(state.contractEvents[i]||[])];$('#modal').close();toast('变更申请已提交','审批前仍按原收款计划执行。')}}
function receiptClaimModal(contractIndex=null,receivableIndex=null){const c=contractIndex===null?contracts[0]:contracts[contractIndex],preset=receivableIndex===null?'':receivables[receivableIndex][4].replaceAll(',','');showModal('到款认领','提交到账信息',section(1,'关联合同',`<div class="form-grid"><div class="field full"><label>合同 <em>*</em></label><select id="receiptContract">${contracts.map((r,i)=>`<option ${i===(contractIndex||0)?'selected':''}>${r[0]} · ${r[1]}</option>`).join('')}</select></div><div class="field"><label>认领金额 <em>*</em></label><input id="receiptAmount" inputmode="numeric" value="${preset}"></div><div class="field"><label>到款日期 <em>*</em></label><input id="receiptDate" type="date" value="2026-07-23"></div><div class="field"><label>付款方 <em>*</em></label><input id="payerName" value="${c[1]}"></div><div class="field"><label>收款账户末四位</label><input id="accountTail" inputmode="numeric" maxlength="4" placeholder="用于财务匹配"></div></div>`)+section(2,'到账证明',`<div class="upload-box" id="receiptUpload"><b>上传银行回单或到账截图</b><small>PDF、PNG或JPG · 单文件不超过10MB · 财务复核可追溯</small></div>`)+section(3,'提交检查',`<div class="health-list"><div class="health-row"><span>ⓘ 关联合同</span><b>${c[0]}</b></div><div class="health-row"><span>ⓘ 财务核销</span><b>提交后进入待复核队列</b></div><div class="health-row"><span>✓ 审计记录</span><b>保存提交人与附件版本</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmReceiptClaim">提交财务复核</button>`);let uploaded=false;$('#receiptUpload').onclick=()=>{uploaded=true;$('#receiptUpload').classList.add('uploaded');$('#receiptUpload').innerHTML='<b>招商银行到账回单.png</b><small>已上传 · 824KB · 可重新选择</small>'};$('#confirmReceiptClaim').onclick=e=>{e.preventDefault();if(!$('#receiptAmount').value||!$('#receiptDate').value||!$('#payerName').value.trim()||!uploaded)return toast('到款信息未完整','金额、日期、付款方和到账证明均为必填项。');$('#modal').close();state.financeTab='reconciliation';render('sales');toast('到款认领已提交','已进入财务复核队列，合同实收尚未更新。')}}
function reconcileReceiptModal(i){const r=receiptClaims[i];showModal('财务复核','确认到款核销',section(1,'匹配结果',`<div class="commit-summary"><div><small>到账金额</small><b>¥${r[3]}</b></div><div><small>关联合同</small><b>${r[1]}</b></div><div><small>付款方</small><b>${r[2]}</b></div></div>`)+section(2,'核销处理',`<div class="form-grid"><div class="field"><label>核销应收节点 <em>*</em></label><select><option>二期款 · ¥240,000</option></select></div><div class="field"><label>核销金额 <em>*</em></label><input id="reconcileAmount" value="${r[3].replaceAll(',','')}"></div><div class="field full"><label>财务备注</label><textarea placeholder="选填，记录差额或特殊情况"></textarea></div></div>`)+section(3,'确认后影响',`<div class="health-list"><div class="health-row"><span>✓ 到款认领单</span><b>标记已核销</b></div><div class="health-row"><span>✓ 合同实收与应收余额</span><b>同步更新</b></div><div class="health-row"><span>ⓘ 法定会计凭证</span><b>仍由财务外部流程处理</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmReconcile">确认核销</button>`);$('#confirmReconcile').onclick=e=>{e.preventDefault();if(!$('#reconcileAmount').value)return toast('请填写核销金额','核销金额不能为空。');state.receiptsReviewed.push(i);$('#modal').close();render('sales');toast('到款已核销','合同实收与应收余额已更新，操作记录已保存。')}}
function initiationModal(){showModal('项目立项','从商务交接发起项目',section(1,'成交与交接输入',`<div class="form-grid"><div class="field"><label>客户合同</label><input value="HT-260718 · 星河制造" disabled></div><div class="field"><label>交付类型</label><input value="AI定制开发" disabled></div><div class="field full"><label>项目目标 <em>*</em></label><textarea id="projectGoal">在合同范围内完成企业数据智能平台二期建设并通过客户验收。</textarea></div><div class="field full"><label>交付范围摘要 <em>*</em></label><textarea id="projectScope">数据接口接入、智能分析模块、管理后台升级和上线培训。</textarea></div></div>`)+section(2,'负责人和资源',`<div class="form-grid"><div class="field"><label>建议项目负责人 <em>*</em></label><select id="suggestedPm"><option>陈浩 · 项目负责人</option><option>许哲 · 技术负责人</option></select><small>由直属负责人或经营管理角色确认。</small></div><div class="field"><label>计划周期 <em>*</em></label><input value="2026-07-28 至 2026-10-31"></div><div class="field full"><label>所需角色</label><div class="chip-row"><span class="choice-chip selected">✓ 产品角色</span><span class="choice-chip selected">✓ 技术负责人</span><span class="choice-chip selected">✓ 开发</span><span class="choice-chip selected">✓ 测试</span><span class="choice-chip selected">✓ 讲师</span></div></div></div>`)+section(3,'启动条件与提交检查',`<div class="health-list"><div class="health-row"><span>✓ 合同已生效</span><b>HT-260718</b></div><div class="health-row"><span>✓ 收款条件已核验</span><b>财务角色已确认</b></div><div class="health-row"><span>✓ 商务交接信息</span><b>范围、联系人、承诺完整</b></div><div class="health-row"><span>ⓘ 部门资源</span><b>提交后由涉及部门确认</b></div></div>`),`<button class="button" value="cancel">保存草稿</button><button class="button primary" id="confirmInitiation">提交立项申请</button>`);$('#confirmInitiation').onclick=e=>{e.preventDefault();if(!$('#projectGoal').value.trim()||!$('#projectScope').value.trim())return toast('立项信息未完整','项目目标和交付范围摘要均为必填项。');state.projectInitiated=true;$('#modal').close();render('projects');toast('立项申请已提交','当前进入部门资源确认，项目负责人尚待角色审批确认。')}}
function resourceConfirmModal(i){const roles=[['技术负责人','技术支持','许哲','160h','无冲突'],['讲师','讲师部','周启明','16h','存在冲突'],['内容运营','新媒体部','林溪','80h/月','待检查']][i];showModal('部门资源确认',`确认${roles[0]}投入`,section(1,'资源需求',`<div class="commit-summary"><div><small>涉及部门</small><b>${roles[1]}</b></div><div><small>建议成员</small><b>${roles[2]}</b></div><div><small>计划投入</small><b>${roles[3]}</b></div></div>`)+section(2,'部门确认',`<div class="radio-cards"><div class="radio-card selected" data-resource-choice="accept"><b>确认投入</b><small>确认成员、投入量和计划周期，形成部门资源承诺。</small></div><div class="radio-card" data-resource-choice="adjust"><b>调整后确认</b><small>更换成员或调整投入量后再确认。</small></div><div class="radio-card" data-resource-choice="reject"><b>暂不接受</b><small>说明资源冲突并退回项目发起人协调。</small></div></div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>确认说明 <em>*</em></label><textarea id="resourceNote" placeholder="说明排期、替代资源或冲突原因"></textarea></div></div>`)+section(3,'排期检查',`<div class="health-list"><div class="health-row"><span>${roles[4]==='无冲突'?'✓':'⚠'} 当前检查结果</span><b>${roles[4]}</b></div><div class="health-row"><span>ⓘ 确认后</span><b>项目与部门均可查看承诺投入</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmResource">提交部门确认</button>`);$$('[data-resource-choice]').forEach(x=>x.onclick=()=>{$$('[data-resource-choice]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected')});$('#confirmResource').onclick=e=>{e.preventDefault();if(!$('#resourceNote').value.trim())return toast('请填写确认说明','资源投入、调整或拒绝都必须说明依据。');$('#modal').close();toast('部门确认已提交','成员、投入和排期结论已写入立项审批轨迹。')}}
function projectBaselineModal(){if(state.projectBaseline)return projectChangeModal();showModal('计划基线','制定项目执行基线',section(1,'基线范围',`<div class="form-grid"><div class="field"><label>项目</label><input value="PJ-260721 · 星河制造数据平台" disabled></div><div class="field"><label>计划周期</label><input value="06-18 至 09-30" disabled></div><div class="field full"><label>基线说明 <em>*</em></label><textarea id="baselineNote">以已确认需求范围、里程碑成果和客户验收口径作为执行基线。</textarea></div></div>`)+section(2,'里程碑完整性',`<div class="health-list"><div class="health-row"><span>✓ 需求基线确认</span><b>成果与验收标准已填写</b></div><div class="health-row"><span>✓ 技术方案确认</span><b>负责人和计划日期已填写</b></div><div class="health-row"><span>✓ 系统联调</span><b>依赖和完成证据已填写</b></div><div class="health-row"><span>✓ UAT与正式验收</span><b>客户确认节点已填写</b></div></div>`)+section(3,'发布检查',`<div class="health-list"><div class="health-row"><span>✓ 项目角色</span><b>责任归属完整</b></div><div class="health-row"><span>✓ 任务与工时</span><b>已从里程碑拆分</b></div><div class="health-row"><span>ⓘ 生效后修改</span><b>必须走变更流程</b></div></div>`),`<button class="button" value="cancel">保存草稿</button><button class="button primary" id="confirmBaseline">提交基线确认</button>`);$('#confirmBaseline').onclick=e=>{e.preventDefault();if(!$('#baselineNote').value.trim())return toast('请填写基线说明','基线说明不能为空。');state.projectBaseline=true;$('#modal').close();render('projects');toast('计划基线已提交确认','当前版本保持可追溯，确认后成为新的执行依据。')}}
function projectRiskModal(){showModal('风险与问题','新增项目风险',section(1,'风险描述',`<div class="form-grid"><div class="field full"><label>风险事项 <em>*</em></label><input id="riskTitle" placeholder="描述可能影响计划或验收的事项"></div><div class="field"><label>影响等级 <em>*</em></label><select><option>高</option><option>中</option><option>低</option></select></div><div class="field"><label>责任角色 <em>*</em></label><select><option>项目负责人</option><option>技术负责人</option><option>商务责任人</option></select></div><div class="field full"><label>影响与应对措施 <em>*</em></label><textarea id="riskResponse" placeholder="说明影响范围、触发条件和应对计划"></textarea></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmRisk">保存风险</button>`);$('#confirmRisk').onclick=e=>{e.preventDefault();if(!$('#riskTitle').value.trim()||!$('#riskResponse').value.trim())return toast('风险信息未完整','风险事项和应对措施均为必填项。');$('#modal').close();toast('项目风险已登记','已指定责任角色并进入持续监控。')}}
