function meetingModal(){showModal('新建排期','创建会议与人员排期',section(1,'会议类型',`<div class="radio-cards"><div class="radio-card selected" data-radio><b>内部培训会议</b><small>用于员工培训和内部知识传递。</small></div><div class="radio-card" data-radio><b>外部线下沙龙</b><small>用于产品宣讲和客户交流，不管理会议室。</small></div></div>`)+section(2,'时间与参与人',`<div class="form-grid"><div class="field full"><label>会议主题 <em>*</em></label><input id="meetingTitle" value="企业AI落地案例分享"></div><div class="field"><label>开始时间 <em>*</em></label><input type="datetime-local" value="2026-07-24T14:30"></div><div class="field"><label>结束时间 <em>*</em></label><input type="datetime-local" value="2026-07-24T16:30"></div><div class="field"><label>主讲人 <em>*</em></label><select><option>周启明 · 高级讲师</option><option>林溪 · 讲师</option></select><small>选择后将自动检查讲师时间冲突。</small></div><div class="field"><label>组织者 <em>*</em></label><select><option>王晨 · 市场销售中心</option></select></div></div>`)+section(3,'发布检查',`<div class="health-list"><div class="health-row"><span>✓ 主题与类型</span><b>已填写</b></div><div class="health-row"><span>✓ 时间范围</span><b>2小时</b></div><div class="health-row"><span>ⓘ 飞书日历</span><b>创建后同步</b></div></div>`),`<button class="button" value="cancel">保存草稿</button><button class="button primary" value="confirm" id="confirmMeeting">创建并同步日历</button>`);$$('[data-radio]').forEach(x=>x.onclick=()=>{$$('[data-radio]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected')});$('#confirmMeeting').onclick=e=>{e.preventDefault();$('#modal').close();toast('排期已创建','已进入飞书日历同步队列，冲突检查通过。')}}
function parseCsvRows(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field.trim());field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field=''}else field+=c}row.push(field.trim());if(row.some(Boolean))rows.push(row);return rows}
function importLeadsModal(){showModal('批量导入','导入公共线索',section(1,'下载标准模板',`<div class="health-list"><div class="health-row"><span>必填字段</span><b>客户主体、联系电话、需求方向</b></div><div class="health-row"><span>可选字段</span><b>联系人、信用代码、企业域名</b></div><div class="health-row"><span>本次录入人</span><b>王晨</b></div></div><button class="button small" id="downloadLeadTemplate" style="margin-top:12px">下载CSV模板</button>`)+section(2,'选择导入文件',`<label class="upload-box" id="leadImportBox" for="leadImportFile"><b>选择CSV文件</b><small>UTF-8编码 · 不超过5MB · 首行为字段名称</small></label><input id="leadImportFile" type="file" accept=".csv,text/csv" hidden>`)+section(3,'导入规则',`<div class="health-list"><div class="health-row"><span>✓ 文件内每条数据自动查重</span><b>提交前完成</b></div><div class="health-row"><span>ⓘ 疑似重复数据</span><b>不导入，不自动合并</b></div><div class="health-row"><span>✓ 干净数据</span><b>进入公共线索池</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="validateLeadImport" disabled>校验数据</button>`);let selectedFile=null;const input=$('#leadImportFile'),box=$('#leadImportBox'),next=$('#validateLeadImport');$('#downloadLeadTemplate').onclick=e=>{e.preventDefault();const csv='\ufeff客户主体,联系人,联系电话,需求方向,统一社会信用代码,企业域名\n示例科技有限公司,张三,13800000000,AI产品销售,,example.com',url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='线索批量导入模板.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('模板已生成','请按模板字段填写后重新上传。')};input.onchange=()=>{selectedFile=input.files[0]||null;if(!selectedFile)return;if(selectedFile.size>5*1024*1024){selectedFile=null;input.value='';return toast('文件过大','请选择不超过5MB的CSV文件。')}box.classList.add('uploaded');box.innerHTML=`<b>${esc(selectedFile.name)}</b><small>${(selectedFile.size/1024).toFixed(1)}KB · 已选择，可重新选择</small>`;next.disabled=false};next.onclick=async e=>{e.preventDefault();if(!selectedFile)return;let rows;try{rows=parseCsvRows(await selectedFile.text())}catch{return toast('文件读取失败','请确认文件为UTF-8编码的CSV格式。')}if(rows.length<2)return toast('没有可导入数据','文件需要包含字段表头和至少一条线索。');const headers=rows[0].map(x=>x.replace(/^\ufeff/,'')),required=['客户主体','联系电话','需求方向'];if(required.some(x=>!headers.includes(x)))return toast('模板字段不完整','必须包含客户主体、联系电话和需求方向。');const index=name=>headers.indexOf(name),allowed=['AI产品销售','AI定制开发','自媒体代运营'],records=rows.slice(1).map((r,n)=>{const company=(r[index('客户主体')]||'').trim(),phone=(r[index('联系电话')]||'').trim(),need=(r[index('需求方向')]||'').trim(),contact=index('联系人')>=0?(r[index('联系人')]||'').trim():'';let result='可导入',reason='字段完整且未发现确定重复';if(!company||!phone||!need||!allowed.includes(need)){result='数据错误';reason='必填字段缺失或需求方向不在标准选项中'}else if(leads.some(x=>x[0]===company)){result='疑似重复';reason='客户主体与已有线索一致'}return{row:n+2,company,phone,need,contact,result,reason}});$('#modal').close();leadImportPreview(selectedFile.name,records)} }
function leadImportPreview(fileName,records){const ready=records.filter(x=>x.result==='可导入'),duplicate=records.filter(x=>x.result==='疑似重复'),invalid=records.filter(x=>x.result==='数据错误');showModal('批量导入','确认校验结果',section(1,'文件与校验汇总',`<div class="commit-summary"><div><small>文件</small><b>${esc(fileName)}</b></div><div><small>可导入</small><b>${ready.length}条</b></div><div><small>疑似重复 / 错误</small><b>${duplicate.length} / ${invalid.length}</b></div></div>`)+section(2,'数据明细',`<div class="import-preview">${records.slice(0,8).map(x=>`<div class="import-row"><span><b>第${x.row}行 · ${esc(x.company||'未填写客户')}</b><small>${esc(x.phone||'无电话')} · ${esc(x.need||'无需求方向')}</small></span>${status(x.result,x.result==='可导入'?'good':x.result==='疑似重复'?'warn':'bad')}<small>${esc(x.reason)}</small></div>`).join('')}</div>${records.length>8?`<p class="import-more">另有 ${records.length-8} 条数据未展开</p>`:''}`)+section(3,'确认后处理',`<div class="health-list"><div class="health-row"><span>可导入数据</span><b>进入公共线索池，录入人为王晨</b></div><div class="health-row"><span>疑似重复数据</span><b>不自动合并，保留在校验结果中</b></div><div class="health-row"><span>错误数据</span><b>不导入，修改后可重新上传</b></div></div>`),`<button class="button" id="backLeadImport">重新选择文件</button><button class="button primary" id="confirmLeadImport" ${ready.length?'':'disabled'}>确认导入 ${ready.length} 条</button>`);$('#backLeadImport').onclick=e=>{e.preventDefault();$('#modal').close();importLeadsModal()};$('#confirmLeadImport').onclick=e=>{e.preventDefault();ready.forEach(x=>leads.push([esc(x.company),x.need,'待补充','待领取','公共','刚刚','普通']));$('#modal').close();state.salesTab='pool';render('sales');toast('批量导入完成',`${ready.length}条线索已进入公共池；${duplicate.length}条疑似重复、${invalid.length}条错误未导入。`)}}
function leadModal(){showModal('录入线索','新增线索',section(1,'客户信息',`<div class="form-grid"><div class="field full"><label>客户主体 <em>*</em></label><input id="leadCompany" placeholder="请输入企业或客户名称"><small>系统按主体名称、统一社会信用代码、手机号和企业域名组合自动查重。</small></div><div class="field"><label>统一社会信用代码</label><input id="leadCredit" placeholder="选填"></div><div class="field"><label>企业域名</label><input id="leadDomain" placeholder="例如 example.com"></div><div class="field"><label>联系人</label><input placeholder="姓名"></div><div class="field"><label>联系电话 <em>*</em></label><input id="leadPhone" inputmode="tel" placeholder="手机号"></div><div class="field"><label>需求方向 <em>*</em></label><select><option>AI产品销售</option><option>AI定制开发</option><option>自媒体代运营</option></select></div><div class="field"><label>录入人</label><input value="王晨" disabled></div></div>`)+section(2,'自动实时查重',`<div class="duplicate-result" id="duplicateResult"><span class="duplicate-mark">查</span><div><b>等待输入客户信息</b><small>填写客户主体和联系电话后，系统自动执行查重。</small></div></div>`)+section(3,'提交检查',`<div class="health-list" id="leadChecks"><div class="health-row"><span>客户主体</span><b>待填写</b></div><div class="health-row"><span>联系电话</span><b>待填写</b></div><div class="health-row"><span>自动查重</span><b>待填写</b></div></div>`),`<button class="button" value="cancel">取消</button><button class="button primary" id="confirmLead" disabled>提交线索</button>`);let checked=false,review=false,checking=false,timer=null,version=0;const company=$('#leadCompany'),phone=$('#leadPhone'),credit=$('#leadCredit'),domain=$('#leadDomain'),result=$('#duplicateResult'),submit=$('#confirmLead');function updateChecks(){const ready=company.value.trim()&&phone.value.trim(),checkText=checking?'正在自动查重':checked?(review?'疑似重复，转人工复核':'未发现确定重复'):ready?'等待自动查重':'待填写';$('#leadChecks').innerHTML=`<div class="health-row"><span>${company.value.trim()?'✓':'⚠'} 客户主体</span><b>${company.value.trim()?'已填写':'待填写'}</b></div><div class="health-row"><span>${phone.value.trim()?'✓':'⚠'} 联系电话</span><b>${phone.value.trim()?'已填写':'待填写'}</b></div><div class="health-row"><span>${checked?'✓':'ⓘ'} 自动查重</span><b>${checkText}</b></div>`;submit.disabled=!ready||checking||!checked}function scheduleDuplicateCheck(){clearTimeout(timer);version+=1;checked=false;review=false;checking=false;const ready=company.value.trim()&&phone.value.trim();result.className='duplicate-result';if(!ready){result.innerHTML='<span class="duplicate-mark">查</span><div><b>等待输入客户信息</b><small>填写客户主体和联系电话后，系统自动执行查重。</small></div>';updateChecks();return}checking=true;result.innerHTML='<span class="duplicate-mark">…</span><div><b>正在自动查重</b><small>正在比对客户主体、信用代码、手机号和企业域名。</small></div>';updateChecks();const currentVersion=version;timer=setTimeout(()=>{if(currentVersion!==version)return;checking=false;checked=true;review=/星河|北辰/.test(company.value);result.className=`duplicate-result ${review?'review':'clear'}`;result.innerHTML=review?'<span class="duplicate-mark">审</span><div><b>发现 1 条疑似重复记录</b><small>不会自动合并；提交后进入人工复核队列。</small></div>':'<span class="duplicate-mark">✓</span><div><b>自动查重完成，未发现确定重复</b><small>可以提交；本次查重条件和结果将写入操作记录。</small></div>';updateChecks()},500)}[company,phone,credit,domain].forEach(x=>x.addEventListener('input',scheduleDuplicateCheck));updateChecks();submit.onclick=e=>{e.preventDefault();if(submit.disabled)return;$('#modal').close();toast(review?'已提交人工复核':'线索录入成功',review?'疑似重复线索已进入复核队列，未发生强制合并。':'线索已保存，录入人王晨及自动查重结果已记录。')}}
function ticketModal(taskIndex=null){const task=taskIndex===null?null:projectTasks[taskIndex];showModal('发起协作','创建跨部门工单',section(1,'业务关联',`<div class="form-grid"><div class="field"><label>关联项目</label><select id="ticketProject"><option>${task?task[2]:'星河制造数据平台'}</option><option>不关联项目</option></select></div><div class="field"><label>关联项目任务</label><select id="ticketTask"><option>${task?task[0]+' · '+task[1]:'RW-072301 · 完成数据接口联调'}</option><option>不关联任务</option></select></div></div>`)+section(2,'请求内容',`<div class="form-grid"><div class="field full"><label>工单标题 <em>*</em></label><input id="ticketTitle" value="${task?'协作支持：'+task[1]:'客户方案需要技术评估'}"></div><div class="field"><label>承接部门 <em>*</em></label><select id="ticketDepartment"><option>技术支持</option><option>讲师部</option><option>财务部</option><option>新媒体部</option></select></div><div class="field"><label>工单分类 <em>*</em></label><select><option>项目交付工单</option><option>普通跨部门协作</option><option>紧急客户或生产问题</option></select><small>分类决定响应、完成和升级规则。</small></div><div class="field"><label>优先级 <em>*</em></label><select id="ticketPriority"><option>中</option><option>高</option><option>低</option></select></div><div class="field"><label>期望完成时间 <em>*</em></label><input type="datetime-local" value="2026-07-24T18:00"></div><div class="field full"><label>期望结果与验收标准 <em>*</em></label><textarea id="ticketExpectation">请提供可验收的处理结果，并说明差异和风险。</textarea></div></div>`)+section(3,'责任与SLA',`<div class="form-grid"><div class="field"><label>验收人 <em>*</em></label><select><option>王洋 · 发起部门</option></select></div><div class="field"><label>当前SLA</label><input value="2个工作小时内响应 · 完成时间按项目计划" disabled></div></div>`),`<button class="button" value="cancel">保存草稿</button><button class="button primary" id="confirmTicket">提交工单</button>`);$('#confirmTicket').onclick=e=>{e.preventDefault();const title=$('#ticketTitle').value.trim(),expectation=$('#ticketExpectation').value.trim();if(!title||!expectation)return toast('工单信息未完整','标题和期望结果与验收标准均为必填项。');const taskValue=$('#ticketTask').value,projectValue=$('#ticketProject').value,link=taskValue==='不关联任务'?(projectValue==='不关联项目'?'未关联':projectValue):taskValue.split(' · ')[0],id=`TK-0723${String(tickets.length+1).padStart(2,'0')}`;tickets.push([id,title,'市场销售中心',$('#ticketDepartment').value,$('#ticketPriority').value,'等待接单',link,'王']);state.ticketStatus.push('待接收');$('#modal').close();render('tickets');toast('工单已提交',`${id} 已显示在“待接收”列，并已通知承接部门。`)}}
