function bindAccountMenu(){const button=$('#accountButton'),menu=$('#accountMenu');const close=()=>{menu.hidden=true;button.setAttribute('aria-expanded','false')};button.onclick=e=>{e.stopPropagation();const opening=menu.hidden;menu.hidden=!opening;button.setAttribute('aria-expanded',String(opening))};menu.onclick=e=>e.stopPropagation();document.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});$$('[data-account-action]',menu).forEach(x=>x.onclick=()=>{const action=x.dataset.accountAction;close();if(action==='profile')accountProfileModal();if(action==='notifications')openNotificationCenter();if(action==='permissions')accountPermissionsModal();if(action==='logout')accountLogoutModal()})}
const commands=[['客户','星河制造','AI定制开发 · 重点客户','sales'],['项目','企业数据智能平台','总体进度 68% · 高风险','projects'],['员工','周启明','讲师部 · 高级讲师','people'],['知识','项目变更与基线管理规范','云文档 V3.2','knowledge'],['工单','销售方案需技术评估','剩余 1h 42m','tickets']];
function renderCommand(q){const rows=commands.filter(x=>(x.join('')).includes(q));$('#commandResults').innerHTML=rows.map(x=>`<button class="command-result" data-command-view="${x[3]}"><span class="source-icon">${x[0][0]}</span><span><b>${x[1]}</b><small>${x[2]}</small></span></button>`).join('')||'<div style="padding:28px;text-align:center;color:var(--ink-3)">没有匹配结果</div>';$$('[data-command-view]').forEach(x=>x.onclick=()=>{closeCommand();render(x.dataset.commandView)})}
